    -moz-user-select: none;
    background: var(--tg-primary-color)0 0;
    border: medium;
    border-radius: 10px;
    cursor: pointer;
    display: inline-block;
    font-size: 15px;
    font-weight: 700;
    letter-spacing: .5px;
    margin-bottom: 0;
    padding: 18px 25px;
    text-align: center;
    touch-action: manipulation;
    transition: all .3s ease 0s;
    align-items: center;
    white-space: nowrap;
    overflow: hidden
}

.btn span {
    background: var(--tg-secondary-color)0 0;
    border-radius: 50%;
    display: block;
    height: 0;
    position: absolute;
    transform: translate(-50%, -50%);
    -moz-transform: translate(-50%, -50%);
    -webkit-transform: translate(-50%, -50%);
    -ms-transform: translate(-50%, -50%);
    -o-transform: translate(-50%, -50%);
    transition: width .6s ease 0s, height .6s ease 0s;
    -moz-transition: width .6s ease 0s, height .6s ease 0s;
    -webkit-transition: width .6s ease 0s, height .6s ease 0s;
    -ms-transition: width .6s ease 0s, height .6s ease 0s;
    -o-transition: width .6s ease 0s, height .6s ease 0s;
    width: 0;
    z-index: -1
}

